class UsersPresenter(private val repo: UserRepository) {
    private val disposables = CompositeDisposable()      // ręczne sprzątanie

    fun search(queries: Observable<String>) {
        disposables += queries
            .debounce(350, TimeUnit.MILLISECONDS)
            .distinctUntilChanged()
            .switchMap { query -> repo.getUsers(query).toObservable() }
            .subscribeOn(Schedulers.io())
            .observeOn(AndroidSchedulers.mainThread())
            .subscribe(
                { users -> view.showUsers(users) },
                { error -> view.showError(error.message) },
            )
    }

    fun onDestroy() { disposables.clear() }              // zapomnisz → wyciek
}

class UsersViewModel(private val searchUsers: SearchUsersUseCase) : ViewModel() {
    fun search(queries: Flow<String>) {
        viewModelScope.launch {                          // scope sprząta sam
            queries
                .debounce(350)
                .distinctUntilChanged()
                .flatMapLatest { query -> flow { emit(searchUsers(query)) } }
                .catch { error -> dispatch(LoadFailed(error.message)) }
                .collect { users -> dispatch(LoadSucceeded(users)) }
        }
    }
}

